1	//! GLM5.2 constants and config probing.
2	
3	use anyhow::Context;
4	use anyhow::Result;
5	use anyhow::bail;
6	use anyhow::ensure;
7	use serde_json::Value;
8	
9	pub(crate) const GLM52_HIDDEN: usize = 6144;
10	pub(crate) const GLM52_VOCAB: usize = 154_880;
11	pub(crate) const GLM52_LAYERS: usize = 78;
12	/// Checkpoint layer containing the native multi-token prediction decoder.
13	pub(crate) const GLM52_MTP_LAYER: usize = GLM52_LAYERS;
14	pub(crate) const GLM52_DENSE_LAYERS: usize = 3;
15	/// The checkpoint's `max_position_embeddings` — `probe_config_json` pins the
16	/// config to exactly this, so it doubles as the architecture ceiling any
17	/// launch-time `max_model_len` must respect.
18	pub(crate) const GLM52_MAX_CONTEXT: usize = 1_048_576;
19	
20	pub(crate) const GLM52_HEADS: usize = 64;
21	const GLM52_KV_HEADS: usize = 64;
22	const GLM52_HEAD_DIM: usize = 192;
23	pub(crate) const GLM52_Q_LORA_RANK: usize = 2048;
24	pub(crate) const GLM52_KV_LORA_RANK: usize = 512;
25	pub(crate) const GLM52_QK_NOPE_HEAD_DIM: usize = 192;
26	pub(crate) const GLM52_QK_ROPE_HEAD_DIM: usize = 64;
27	pub(crate) const GLM52_QK_HEAD_DIM: usize = GLM52_QK_NOPE_HEAD_DIM + GLM52_QK_ROPE_HEAD_DIM;
28	pub(crate) const GLM52_V_HEAD_DIM: usize = 256;
29	pub(crate) const GLM52_Q_B_OUT: usize = GLM52_HEADS * GLM52_QK_HEAD_DIM;
30	pub(crate) const GLM52_KV_A_OUT: usize = GLM52_KV_LORA_RANK + GLM52_QK_ROPE_HEAD_DIM;
31	pub(crate) const GLM52_KV_B_OUT: usize = GLM52_HEADS * (GLM52_QK_NOPE_HEAD_DIM + GLM52_V_HEAD_DIM);
32	pub(crate) const GLM52_O_PROJ_IN: usize = GLM52_HEADS * GLM52_V_HEAD_DIM;
33	
34	/// Half of the rotary head dim — the rotary table width shared by MLA and
35	/// indexer rope.
36	pub(crate) const GLM52_ROPE_HALF: usize = GLM52_QK_ROPE_HEAD_DIM / 2;
37	/// `1/sqrt(GLM52_QK_HEAD_DIM)` = 1/sqrt(256) = 0.0625 — the MLA softmax scale
38	/// (rope_type "default" means no YaRN mscale correction).
39	pub(crate) const GLM52_SM_SCALE: f32 = 0.0625;
40	
41	pub(crate) const GLM52_DENSE_INTERMEDIATE: usize = 12_288;
42	pub(crate) const GLM52_EXPERT_INTERMEDIATE: usize = 2048;
43	pub(crate) const GLM52_ROUTED_EXPERTS: usize = 256;
44	pub(crate) const GLM52_TOPK: usize = 8;
45	const GLM52_SHARED_EXPERTS: usize = 1;
46	pub(crate) const GLM52_ROUTED_SCALING_FACTOR: f64 = 2.5;
47	const GLM52_RMS_NORM_EPS: f64 = 1.0e-5;
48	/// The f32 the GPU norm kernels consume (every RMSNorm in the model shares
49	/// the one checkpoint eps that `probe_config_json` validates).
50	pub(crate) const GLM52_RMS_EPS: f32 = GLM52_RMS_NORM_EPS as f32;
51	
52	pub(crate) const GLM52_INDEX_TOPK: usize = 2048;
53	const GLM52_INDEX_TOPK_FREQ: usize = 4;
54	pub(crate) const GLM52_INDEX_HEAD_DIM: usize = 128;
55	pub(crate) const GLM52_INDEX_HEADS: usize = 32;
56	const GLM52_INDEX_SKIP_TOPK_OFFSET: usize = 3;
57	const GLM52_NEXTN_LAYERS: usize = 1;
58	
59	pub(crate) const GLM52_ROPE_THETA: f64 = 8_000_000.0;
60	
61	/// `indexer_types[layer]` per the transformers derivation
62	/// (`index_topk_freq=4`, `index_skip_topk_offset=3`): full iff
63	/// `max(layer-(offset-1), 0) % freq == 0` → {0,1,2} ∪ {6,10,…,74}, 21 of 78 layers.
64	pub(crate) fn glm52_layer_has_full_indexer(layer: usize) -> bool {
65	    layer
66	        .saturating_sub(GLM52_INDEX_SKIP_TOPK_OFFSET - 1)
67	        .is_multiple_of(GLM52_INDEX_TOPK_FREQ)
68	}
69	
70	pub(crate) fn probe_config_json(json: &Value) -> Result<()> {
71	    let model_type = string_field(json, "model_type")?;
72	    if model_type != "glm_moe_dsa" {
73	        bail!("not a GLM5.2 config: model_type={model_type}");
74	    }
75	    ensure!(
76	        string_array_field(json, "architectures")?
77	            .iter()
78	            .any(|value| value == "GlmMoeDsaForCausalLM"),
79	        "GLM5.2 architectures must contain GlmMoeDsaForCausalLM"
80	    );
81	    ensure!(
82	        string_field(json, "dtype")? == "bfloat16",
83	        "GLM5.2 dtype must be bfloat16"
84	    );
85	    ensure!(
86	        !bool_field(json, "attention_bias")?,
87	        "GLM5.2 attention_bias must be false"
88	    );
89	    ensure!(
90	        string_field(json, "hidden_act")? == "silu",
91	        "GLM5.2 hidden_act must be silu"
92	    );
93	
94	    ensure_eq_usize(json, "hidden_size", GLM52_HIDDEN)?;
95	    ensure_eq_usize(json, "vocab_size", GLM52_VOCAB)?;
96	    ensure_eq_usize(json, "num_hidden_layers", GLM52_LAYERS)?;
97	    ensure_eq_usize(json, "first_k_dense_replace", GLM52_DENSE_LAYERS)?;
98	    ensure_eq_usize(json, "max_position_embeddings", GLM52_MAX_CONTEXT)?;
99	    ensure_eq_usize(json, "intermediate_size", GLM52_DENSE_INTERMEDIATE)?;
100	    ensure_eq_usize(json, "moe_intermediate_size", GLM52_EXPERT_INTERMEDIATE)?;
101	
102	    ensure_eq_usize(json, "num_attention_heads", GLM52_HEADS)?;
103	    ensure_eq_usize(json, "num_key_value_heads", GLM52_KV_HEADS)?;
104	    ensure_eq_usize(json, "head_dim", GLM52_HEAD_DIM)?;
105	    ensure_eq_usize(json, "q_lora_rank", GLM52_Q_LORA_RANK)?;
106	    ensure_eq_usize(json, "kv_lora_rank", GLM52_KV_LORA_RANK)?;
107	    ensure_eq_usize(json, "qk_nope_head_dim", GLM52_QK_NOPE_HEAD_DIM)?;
108	    ensure_eq_usize(json, "qk_rope_head_dim", GLM52_QK_ROPE_HEAD_DIM)?;
109	    ensure_eq_usize(json, "qk_head_dim", GLM52_QK_HEAD_DIM)?;
110	    ensure_eq_usize(json, "v_head_dim", GLM52_V_HEAD_DIM)?;
111	    ensure!(
112	        bool_field(json, "rope_interleave")?,
113	        "GLM5.2 rope_interleave must be true"
114	    );
115	    let rope = json
116	        .get("rope_parameters")
117	        .ok_or_else(|| anyhow::anyhow!("GLM5.2 config missing rope_parameters"))?;
118	    ensure!(
119	        string_field(rope, "rope_type")? == "default",
120	        "GLM5.2 rope_parameters.rope_type must be default"
121	    );
122	    ensure_float_close(
123	        number_field(rope, "rope_theta")?,
124	        GLM52_ROPE_THETA,
125	        1.0e-6,
126	        "rope_parameters.rope_theta",
127	    )?;
128	
129	    ensure_eq_usize(json, "n_routed_experts", GLM52_ROUTED_EXPERTS)?;
130	    ensure_eq_usize(json, "num_experts_per_tok", GLM52_TOPK)?;
131	    ensure_eq_usize(json, "n_shared_experts", GLM52_SHARED_EXPERTS)?;
132	    ensure_eq_usize(json, "n_group", 1)?;
133	    ensure_eq_usize(json, "topk_group", 1)?;
134	    ensure!(
135	        string_field(json, "topk_method")? == "noaux_tc",
136	        "GLM5.2 topk_method must be noaux_tc"
137	    );
138	    ensure!(
139	        string_field(json, "scoring_func")? == "sigmoid",
140	        "GLM5.2 scoring_func must be sigmoid"
141	    );
142	    ensure!(
143	        bool_field(json, "norm_topk_prob")?,
144	        "GLM5.2 norm_topk_prob must be true"
145	    );
146	    ensure_float_close(
147	        number_field(json, "routed_scaling_factor")?,
148	        GLM52_ROUTED_SCALING_FACTOR,
149	        1.0e-12,
150	        "routed_scaling_factor",
151	    )?;
152	    ensure_float_close(
153	        number_field(json, "rms_norm_eps")?,
154	        GLM52_RMS_NORM_EPS,
155	        1.0e-12,
156	        "rms_norm_eps",
157	    )?;
158	
159	    ensure_eq_usize(json, "index_topk", GLM52_INDEX_TOPK)?;
160	    ensure_eq_usize(json, "index_topk_freq", GLM52_INDEX_TOPK_FREQ)?;
161	    ensure_eq_usize(json, "index_head_dim", GLM52_INDEX_HEAD_DIM)?;
162	    ensure_eq_usize(json, "index_n_heads", GLM52_INDEX_HEADS)?;
163	    ensure_eq_usize(json, "index_skip_topk_offset", GLM52_INDEX_SKIP_TOPK_OFFSET)?;
164	    ensure!(
165	        bool_field(json, "indexer_rope_interleave")?,
166	        "GLM5.2 indexer_rope_interleave must be true"
167	    );
168	
169	    ensure_eq_usize(json, "num_nextn_predict_layers", GLM52_NEXTN_LAYERS)?;
170	    ensure!(
171	        bool_field(json, "index_share_for_mtp_iteration")?,
172	        "GLM5.2 index_share_for_mtp_iteration must be true"
173	    );
174	    ensure!(
175	        !bool_field(json, "tie_word_embeddings")?,
176	        "GLM5.2 tie_word_embeddings must be false"
177	    );
178	    ensure_mlp_layer_types(json)?;
179	    ensure_indexer_types(json)?;
180	    ensure_fp8_quantization(json)?;
181	
182	    Ok(())
183	}
184	
185	fn ensure_mlp_layer_types(json: &Value) -> Result<()> {
186	    let types = string_array_field(json, "mlp_layer_types")?;
187	    ensure!(
188	        types.len() == GLM52_LAYERS,
189	        "GLM5.2 mlp_layer_types length mismatch: got {}, expected {GLM52_LAYERS}",
190	        types.len()
191	    );
192	    for (idx, kind) in types.iter().enumerate() {
193	        let expected = if idx < GLM52_DENSE_LAYERS {
194	            "dense"
195	        } else {
196	            "sparse"
197	        };
198	        ensure!(
199	            kind == expected,
200	            "GLM5.2 mlp_layer_types[{idx}] mismatch: got {kind}, expected {expected}"
201	        );
202	    }
203	    Ok(())
204	}
205	
206	fn ensure_indexer_types(json: &Value) -> Result<()> {
207	    let types = string_array_field(json, "indexer_types")?;
208	    ensure!(
209	        types.len() == GLM52_LAYERS,
210	        "GLM5.2 indexer_types length mismatch: got {}, expected {GLM52_LAYERS}",
211	        types.len()
212	    );
213	    ensure!(
214	        types.iter().all(|kind| kind == "full" || kind == "shared"),
215	        "GLM5.2 indexer_types must contain only full/shared entries"
216	    );
217	    Ok(())
218	}
219	
220	fn ensure_fp8_quantization(json: &Value) -> Result<()> {
221	    let quant = json
222	        .get("quantization_config")
223	        .ok_or_else(|| anyhow::anyhow!("GLM5.2 config missing quantization_config"))?;
224	    ensure!(
225	        string_field(quant, "quant_method")? == "fp8",
226	        "GLM5.2 quantization_config.quant_method must be fp8"
227	    );
228	    ensure!(
229	        string_field(quant, "fmt")? == "e4m3",
230	        "GLM5.2 quantization_config.fmt must be e4m3"
231	    );
232	    ensure!(
233	        string_field(quant, "activation_scheme")? == "dynamic",
234	        "GLM5.2 quantization_config.activation_scheme must be dynamic"
235	    );
236	    let block = quant
237	        .get("weight_block_size")
238	        .and_then(Value::as_array)
239	        .ok_or_else(|| anyhow::anyhow!("GLM5.2 quantization_config.weight_block_size missing"))?;
240	    ensure!(
241	        block.len() == 2 && block[0].as_u64() == Some(128) && block[1].as_u64() == Some(128),
242	        "GLM5.2 weight_block_size must be [128, 128]"
243	    );
244	    Ok(())
245	}
246	
247	fn string_field(json: &Value, key: &str) -> Result<String> {
248	    json.get(key)
249	        .and_then(Value::as_str)
250	        .map(ToOwned::to_owned)
251	        .ok_or_else(|| anyhow::anyhow!("missing string field {key}"))
252	}
253	
254	fn string_array_field(json: &Value, key: &str) -> Result<Vec<String>> {
255	    let values = json
256	        .get(key)
257	        .and_then(Value::as_array)
258	        .ok_or_else(|| anyhow::anyhow!("missing string array field {key}"))?;
259	    values
260	        .iter()
261	        .map(|value| {
262	            value
263	                .as_str()
264	                .map(ToOwned::to_owned)
265	                .ok_or_else(|| anyhow::anyhow!("field {key} contains a non-string entry"))
266	        })
267	        .collect()
268	}
269	
270	fn usize_field(json: &Value, key: &str) -> Result<usize> {
271	    let value = json
272	        .get(key)
273	        .and_then(Value::as_u64)
274	        .ok_or_else(|| anyhow::anyhow!("missing unsigned integer field {key}"))?;
275	    usize::try_from(value).with_context(|| format!("field {key} does not fit usize"))
276	}
277	
278	fn bool_field(json: &Value, key: &str) -> Result<bool> {
279	    json.get(key)
280	        .and_then(Value::as_bool)
281	        .ok_or_else(|| anyhow::anyhow!("missing bool field {key}"))
282	}
283	
284	fn number_field(json: &Value, key: &str) -> Result<f64> {
285	    json.get(key)
286	        .and_then(Value::as_f64)
287	        .ok_or_else(|| anyhow::anyhow!("missing numeric field {key}"))
288	}
289	
290	fn ensure_eq_usize(json: &Value, key: &str, expected: usize) -> Result<()> {
291	    let actual = usize_field(json, key)?;
292	    ensure!(
293	        actual == expected,
294	        "{key} mismatch: got {actual}, expected {expected}"
295	    );
296	    Ok(())
297	}
298	
299	fn ensure_float_close(actual: f64, expected: f64, tolerance: f64, label: &str) -> Result<()> {
300	    ensure!(
301	        (actual - expected).abs() <= tolerance,
302	        "{label} mismatch: got {actual}, expected {expected}"
303	    );
304	    Ok(())
305	}
306

