371	/// Host-tier KV offload knobs. One `PegaEngine` (one pinned pool) backs all
372	/// 8 DP ranks under a single namespace: the MLA latent has no TP sharding
373	/// and the non-expert weights are replicated, so any rank's KV for a token
374	/// prefix is as good as any other's — the same tolerance as reusing a
375	/// rank's own prefix cache (FP reduction order may differ across the batch
376	/// shapes that computed it, never the semantics). Any rank restores what
377	/// any rank saved.
378	#[derive(Clone, Debug)]
379	pub struct Glm52KvOffloadOptions {
380	    /// Host pinned-memory pool size in bytes, shared by all ranks.
381	    pinned_pool_bytes: usize,
382	    /// Back the pool with hugepages (the box must hold a reservation —
383	    /// check `HugePages_Total`).
384	    use_hugepages: bool,
385	    /// `Some` joins the cross-instance P2P mesh: saved block hashes register
386	    /// with the MetaServer and missing prefixes are pulled from peer
387	    /// instances over RDMA — the P/D disaggregation data plane.
388	    p2p: Option<Glm52P2pOptions>,
389	}
390	
391	/// Cross-instance P2P KV sharing (see `pegainfer_kv_store::P2pConfig`).
392	#[derive(Clone, Debug)]
393	pub struct Glm52P2pOptions {
394	    /// MetaServer gRPC address, e.g. `http://10.0.0.100:50056`.
395	    metaserver_addr: String,
396	    /// This engine's routable `IP:port` (doubles as the embedded transfer
397	    /// service's bind address). Must be reachable by every peer.
398	    advertise_addr: String,
399	    /// RDMA NIC device names to register the pinned pool on.
400	    rdma_nics: Vec<String>,
401	}
402	
403	/// GLM5.2 kernels (FlashMLA SM100, DeepGEMM MQA and routed experts, …)
404	/// no longer ship a Hopper path. Refuse SM9x and older at launch.
405	///
406	/// `local_gpus` is the number of GPUs **this process** hosts (mapped to local
407	/// ordinals `0..local_gpus`), not the global EP width — multi-process
408	/// EP16/32/64 shards may own only four devices on a tray.
409	fn ensure_blackwell_devices(local_gpus: usize) -> Result<()> {
410	    ensure!(local_gpus > 0, "GLM5.2 needs at least one GPU");
411	    for ordinal in 0..local_gpus {
412	        let ctx = pegainfer_kernels::tensor::DeviceContext::new_with_device(ordinal)
413	            .with_context(|| format!("GLM5.2 open device {ordinal} for arch check"))?;
414	        let major = ctx.ctx.attribute(
415	            cudarc::driver::sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR,
416	        )?;
417	        let minor = ctx.ctx.attribute(
418	            cudarc::driver::sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR,
419	        )?;
420	        ensure!(
421	            major >= 10,
422	            "GLM5.2 requires Blackwell (compute capability ≥ 10.0); device {ordinal} is \
423	             SM{major}.{minor}. Hopper (SM9x) support was removed."
424	        );
425	    }
426	    Ok(())
427	}
