858	struct Glm52LoadOptions {
859	    /// The global DP ranks this process hosts; its local GPUs are device
860	    /// ordinals `0..ranks.len()`.
861	    ranks: Range<usize>,
862	    /// Bootstrap rendezvous address for a multi-process fleet (see
863	    /// [`Glm52LaunchOptions::rendezvous`]).
864	    rendezvous: Option<String>,
865	    tp_size: usize,
866	    dp_size: usize,
867	    ep_size: usize,
868	}
869	
870	#[derive(Debug)]
871	struct StartupValidation {
872	    /// The global DP ranks this process hosts (`device_ordinal i` serves
873	    /// `ranks.start + i`).
874	    ranks: Range<usize>,
875	    rendezvous: Option<String>,
876	    rank_bundles: Vec<Glm52RankLoadBundle>,
877	    rank_tensor_counts: Vec<usize>,
878	    rank_expert_ranges: Vec<std::ops::Range<usize>>,
879	}
880	
881	#[derive(Debug)]
882	/// Per-rank facts gathered while the weights landed (index = rank).
883	struct GpuWeightLoadReport {
884	    tensor_counts: Vec<usize>,
885	    bytes: Vec<usize>,
886	    free_vram_bytes: Vec<usize>,
887	}
888	
889	struct LoadedGlm52Runtime {
890	    workers: Vec<Glm52Worker>,
891	    report: GpuWeightLoadReport,
892	}
893	
894	fn start_engine(
895	    model_path: &Path,
896	    options: &Glm52LoadOptions,
897	    drafter: Glm52Drafter,
898	    requested_max_model_len: Option<usize>,
899	    prefill_only: Option<Glm52PrefillOnlyOptions>,
900	    no_prefix_cache: bool,
901	    kv_offload: Option<Glm52KvOffloadOptions>,
902	    moe_topo: Glm52MoeTopo,
903	    weight_staging: bool,
904	    dump_graph_png: Option<PathBuf>,
905	) -> Result<EngineHandle> {
906	    let startup = validate_startup(model_path, options, moe_topo, drafter.is_mtp())?;
907	    let loaded = load_rank_weights_to_gpu(model_path, &startup, moe_topo, weight_staging)?;
908	    log::info!(
909	        "GLM5.2 load-weight startup complete: hosted_ranks={:?}, rank_plan_tensors={:?}, rank_gpu_tensors={:?}, rank_gpu_bytes={:?}",
910	        startup.ranks,
911	        startup.rank_tensor_counts,
912	        loaded.report.tensor_counts,
913	        format_bytes(&loaded.report.bytes),
914	    );
915	
916	    let min_free_vram_bytes = loaded
917	        .report
918	        .free_vram_bytes
919	        .iter()
920	        .copied()
921	        .min()
922	        .expect("at least one rank loaded");
923	    // These model-build allocations land after the weight probe. Charge
924	    // exact bytes here so auto mode cannot spend them on KV and then fail the
925	    // post-build graph-capture headroom gate.
