61	/// `indexer_types[layer]` per the transformers derivation
62	/// (`index_topk_freq=4`, `index_skip_topk_offset=3`): full iff
63	/// `max(layer-(offset-1), 0) % freq == 0` → {0,1,2} ∪ {6,10,…,74}, 21 of 78 layers.
64	pub(crate) fn glm52_layer_has_full_indexer(layer: usize) -> bool {
