70	pub(crate) fn probe_config_json(json: &Value) -> Result<()> {
71	    let model_type = string_field(json, "model_type")?;
72	    if model_type != "glm_moe_dsa" {
73	        bail!("not a GLM5.2 config: model_type={model_type}");
74	    }
75	    ensure!(
76	        string_array_field(json, "architectures")?
77	            .iter()
78	            .any(|value| value == "GlmMoeDsaForCausalLM"),
79	        "GLM5.2 architectures must contain GlmMoeDsaForCausalLM"
80	    );
81	    ensure!(
82	        string_field(json, "dtype")? == "bfloat16",
83	        "GLM5.2 dtype must be bfloat16"
84	    );
85	    ensure!(
86	        !bool_field(json, "attention_bias")?,
87	        "GLM5.2 attention_bias must be false"
88	    );
89	    ensure!(
90	        string_field(json, "hidden_act")? == "silu",
91	        "GLM5.2 hidden_act must be silu"
92	    );
93	
94	    ensure_eq_usize(json, "hidden_size", GLM52_HIDDEN)?;
95	    ensure_eq_usize(json, "vocab_size", GLM52_VOCAB)?;
96	    ensure_eq_usize(json, "num_hidden_layers", GLM52_LAYERS)?;
97	    ensure_eq_usize(json, "first_k_dense_replace", GLM52_DENSE_LAYERS)?;
98	    ensure_eq_usize(json, "max_position_embeddings", GLM52_MAX_CONTEXT)?;
99	    ensure_eq_usize(json, "intermediate_size", GLM52_DENSE_INTERMEDIATE)?;
100	    ensure_eq_usize(json, "moe_intermediate_size", GLM52_EXPERT_INTERMEDIATE)?;
101	
102	    ensure_eq_usize(json, "num_attention_heads", GLM52_HEADS)?;
103	    ensure_eq_usize(json, "num_key_value_heads", GLM52_KV_HEADS)?;
104	    ensure_eq_usize(json, "head_dim", GLM52_HEAD_DIM)?;
105	    ensure_eq_usize(json, "q_lora_rank", GLM52_Q_LORA_RANK)?;
106	    ensure_eq_usize(json, "kv_lora_rank", GLM52_KV_LORA_RANK)?;
107	    ensure_eq_usize(json, "qk_nope_head_dim", GLM52_QK_NOPE_HEAD_DIM)?;
108	    ensure_eq_usize(json, "qk_rope_head_dim", GLM52_QK_ROPE_HEAD_DIM)?;
109	    ensure_eq_usize(json, "qk_head_dim", GLM52_QK_HEAD_DIM)?;
