185	fn ensure_mlp_layer_types(json: &Value) -> Result<()> {
186	    let types = string_array_field(json, "mlp_layer_types")?;
187	    ensure!(
188	        types.len() == GLM52_LAYERS,
189	        "GLM5.2 mlp_layer_types length mismatch: got {}, expected {GLM52_LAYERS}",
190	        types.len()
191	    );
192	    for (idx, kind) in types.iter().enumerate() {
193	        let expected = if idx < GLM52_DENSE_LAYERS {
194	            "dense"
195	        } else {
196	            "sparse"
197	        };
198	        ensure!(
199	            kind == expected,
200	            "GLM5.2 mlp_layer_types[{idx}] mismatch: got {kind}, expected {expected}"
201	        );
202	    }
203	    Ok(())
204	}
