255	    let values = json
256	        .get(key)
257	        .and_then(Value::as_array)
258	        .ok_or_else(|| anyhow::anyhow!("missing string array field {key}"))?;
259	    values
260	        .iter()
261	        .map(|value| {
262	            value
263	                .as_str()
264	                .map(ToOwned::to_owned)
265	                .ok_or_else(|| anyhow::anyhow!("field {key} contains a non-string entry"))
266	        })
