141	/// GLM5.2 parallel shape. EP8 is the production layout today; TP4 is the
142	/// GB300 bring-up target.
143	#[derive(Clone, Debug)]
144	pub struct Glm52LaunchOptions {
145	    tp_size: usize,
146	    dp_size: usize,
147	    /// Optional speculative decoder. DSpark enables lossless speculative
148	    /// sampling from an external checkpoint; native MTP uses the checkpoint's
149	    /// layer-78 decoder and supports EP decode (single- or multi-process —
150	    /// the MTP round rides the same fixed chain and DeepEP context as the
151	    /// target steps) and TP4 prefill-only.
152	    drafter: Glm52Drafter,
153	    /// Per-request context cap (`prompt + max_tokens - 1 <= max_model_len`).
154	    /// `None` sizes it from the post-weight-load free VRAM (fleet minimum);
155	    /// an explicit value is still validated against that budget so an
156	    /// impossible cap fails at launch, not at the first long request.
157	    max_model_len: Option<usize>,
158	    /// Enables TP4 prefill-only serving.
159	    prefill_only: Option<Glm52PrefillOnlyOptions>,
160	    /// vLLM-style kill switch: disable prefix matching outright (every
161	    /// prefill recomputes the full prompt). Prefix caching is also forced
162	    /// off while a speculative decoder is on: DSpark needs aux-hidden
163	    /// captures for every prefix row, while native MTP needs target hidden
164	    /// states and uninterrupted MTP KV continuity.
165	    no_prefix_cache: bool,
166	    /// `Some` adds the pegaflow host tier under the prefix cache: sealed KV
167	    /// blocks flow to one shared pinned pool on request release, and a
168	    /// prompt whose prefix fell out of HBM restores from it at admission.
169	    /// Requires the prefix cache (rejected at launch alongside any
170	    /// speculative decoder or `no_prefix_cache`).
171	    kv_offload: Option<Glm52KvOffloadOptions>,
172	    /// Launch-time MoE sharding topology. `Ep8` (default) is the
173	    /// high-throughput configuration: 32 whole experts per rank, DeepEP
174	    /// dispatch/combine, buckets 1-8. `Tp4` is GB300 **prefill-only**
175	    /// tensor parallel (NCCL all-reduce; requires `--glm52-prefill-only`).
176	    moe_topo: Glm52MoeTopo,
177	    /// Stage checkpoint bytes through pinned double buffers. Intended for
178	    /// warm page-cache starts; cold network filesystems should leave it off.
179	    weight_staging: bool,
180	    /// Export rank 0's already pre-captured whole-step decode graph during
181	    /// startup. EP and TP4 export bucket 1. The requested PNG gets a
182	    /// complete sibling `.dot` for machine inspection.
183	    dump_graph_png: Option<PathBuf>,
184	    /// The global DP ranks THIS process hosts (default: the whole topology
185	    /// — the single-node engine). A partial range is the multi-process
186	    /// cross-node shape: every node runs the same binary over its own ranks,
187	    /// and the collective DeepEP communicator is the only coupling
188	    /// (`docs/models/glm52/free-running-dp.md` §3).
189	    ranks: Option<Range<usize>>,
190	    /// Bootstrap rendezvous address, required exactly when `ranks` is a
191	    /// partial range. The process hosting rank 0 binds it and serves the
192	    /// DeepEP unique id; every other process connects to fetch it. A
193	    /// one-time handshake — there is no runtime control plane.
194	    rendezvous: Option<String>,
195	}
