359	            assert_eq!(topo.device_count(), ranks);
360	            assert_eq!(topo.logical_rank_count(), ranks);
361	            assert_eq!(topo.expected_tp_size(), 1);
362	            assert_eq!(topo.expected_ep_size(), ranks);
363	            assert!(topo.uses_ep_expert_bundles());
364	            assert!(!topo.uses_tensor_replicated_moe());
365	            assert_eq!(topo.ep_local_experts(), local);
366	            assert_eq!(format!("ep{ranks}").parse::<Glm52MoeTopo>().unwrap(), topo);
367	        }
368	    }
369	}
