429	fn launch(model_path: &Path, options: Glm52LaunchOptions) -> Result<EngineHandle> {
430	    let Glm52LaunchOptions {
431	        tp_size,
432	        dp_size,
433	        drafter,
434	        max_model_len,
435	        prefill_only,
436	        no_prefix_cache,
437	        kv_offload,
438	        moe_topo,
439	        weight_staging,
440	        dump_graph_png,
441	        ranks,
442	        rendezvous,
443	    } = options;
444	    let device_count = moe_topo.device_count();
445	    let ranks = ranks.unwrap_or(0..device_count);
446	    ensure!(
447	        ranks.start < ranks.end && ranks.end <= device_count,
448	        "GLM5.2 --glm52-ranks {}..{} is outside 0..{device_count} or empty",
449	        ranks.start,
450	        ranks.end
451	    );
452	    // The (slots, drafts) startup pair must fit the step-row budget —
453	    // an over-committed pair would silently cap verify spans under full
454	    // occupancy and collapse speculation (#812's original failure mode).
455	    // Only native MTP rides verify spans; without a drafter every slot is a
456	    // single decode row and any slot count within the ceiling fits.
457	    let slots = model::glm52_decode_slots();
458	    let draft_len = if drafter.is_mtp() {
459	        crate::mtp::glm52_mtp_draft_len()
460	    } else {
461	        0
462	    };
463	    ensure!(
464	        slots * (1 + draft_len) <= model::GLM52_MAX_STEP_ROWS,
465	        "GLM5.2 GLM52_DECODE_SLOTS={slots} x (1 + GLM52_MTP_DRAFTS={draft_len}) exceeds the \
466	         {}-row step budget; 32 slots need GLM52_MTP_DRAFTS=2",
467	        model::GLM52_MAX_STEP_ROWS
468	    );
469	    log::info!(
470	        "GLM5.2 decode profile: slots={slots} mtp_draft_span={draft_len} ({} of {} step rows)",
471	        slots * (1 + draft_len),
472	        model::GLM52_MAX_STEP_ROWS
473	    );
474	    // Probe only the GPUs this process hosts (local ordinals 0..N), not the
475	    // global EP width — EP16 on one 4-GPU tray would otherwise try device 4+.
476	    ensure_blackwell_devices(ranks.end - ranks.start)?;
477	    let multi_process = ranks != (0..device_count);
478	    if moe_topo.uses_tensor_replicated_moe() {
479	        ensure!(
480	            !multi_process,
481	            "GLM5.2 {moe_topo:?} is a single-process topology (its workers rendezvous \
482	             device pointers in-process); --glm52-ranks must cover 0..{device_count}"
483	        );
484	    }
485	    ensure!(
486	        !multi_process || rendezvous.is_some(),
487	        "GLM5.2 hosting ranks {}..{} of {device_count} requires --glm52-rendezvous \
488	         (the rank-0 process binds it, everyone else connects)",
489	        ranks.start,
490	        ranks.end
491	    );
492	    if drafter.is_mtp() {
493	        ensure!(
494	            moe_topo.uses_ep_expert_bundles()
495	                || (moe_topo == Glm52MoeTopo::Tp4 && prefill_only.is_some()),
496	            "GLM5.2 native MTP requires EP decode or TP4 prefill-only"
497	        );
498	    }
499	    if let Some(path) = &dump_graph_png {
500	        ensure!(
501	            ranks.start == 0,
502	            "GLM5.2 --dump-graph-png only works on the process hosting rank 0"
503	        );
504	        pegainfer_core::cuda_graph::validate_graph_dump_request(path)?;
505	    }
506	    match moe_topo {
507	        Glm52MoeTopo::Tp4 => {
508	            ensure!(
509	                tp_size == 4,
510	                "GLM5.2 TP4 requires --tp-size=4, got {tp_size}"
511	            );
512	            ensure!(
513	                dp_size == 1,
514	                "GLM5.2 TP4 requires --dp-size=1 (or omitted), got {dp_size}"
515	            );
516	            ensure!(
517	                prefill_only.is_some(),
518	                "GLM5.2 TP4 is prefill-only: pass --glm52-prefill-only \
519	                 (decode TP / LL packet path was removed)"
520	            );
521	        }
522	        _ => {
523	            ensure!(
524	                tp_size == 1,
525	                "GLM5.2 {moe_topo:?} requires --tp-size=1, got {tp_size}"
526	            );
527	            let expected_dp = moe_topo.default_dp_size();
528	            ensure!(
529	                dp_size == expected_dp,
530	                "GLM5.2 {moe_topo:?} requires --dp-size={expected_dp} (or omitted), got {dp_size}"
531	            );
532	        }
533	    }
534	    if let Some(prefill) = prefill_only {
535	        ensure!(
536	            moe_topo == Glm52MoeTopo::Tp4,
537	            "GLM5.2 prefill-only mode requires the TP4 topology"
538	        );
539	        ensure!(
540	            prefill.chunk_size > 0 && prefill.chunk_size.is_multiple_of(GLM52_PREFILL_CHUNK_ALIGN),
541	            "GLM5.2 prefill chunk size {} must be a positive multiple of {}",
542	            prefill.chunk_size,
543	            GLM52_PREFILL_CHUNK_ALIGN,
544	        );
545	        ensure!(
546	            !drafter.is_dspark(),
547	            "GLM5.2 prefill-only mode is incompatible with DSpark"
548	        );
549	        ensure!(
550	            !no_prefix_cache,
551	            "GLM5.2 prefill-only mode requires prefix caching"
552	        );
553	        ensure!(
554	            kv_offload.is_none() || drafter.is_mtp(),
555	            "GLM5.2 prefill-only KV offload requires native MTP's 101-arena contract"
556	        );
557	        ensure!(
558	            dump_graph_png.is_none(),
559	            "GLM5.2 prefill-only mode does not expose a decode CUDA graph"
560	        );
561	    }
562	    // The offload tier extends the prefix cache (restored blocks surface as
563	    // matched prefix), so a config that disables prefix matching while asking
564	    // for offload is contradictory — fail loud instead of silently idling an
565	    // allocated multi-GiB pinned pool.
566	    ensure!(
567	        kv_offload.is_none() || ((!drafter.enabled() || drafter.is_mtp()) && !no_prefix_cache),
568	        "GLM5.2 --kv-offload requires the prefix cache: drop --no-prefix-cache and the \
569	         DSpark drafter"
570	    );
571	    // The TP topology mirrors KV on every rank; the host tier's restore leg
572	    // H2Ds into ONE rank's arena, which would silently desync the other 7.
573	    ensure!(
574	        kv_offload.is_none()
575	            || moe_topo.uses_ep_expert_bundles()
576	            || (moe_topo == Glm52MoeTopo::Tp4 && prefill_only.is_some()),
577	        "GLM5.2 --kv-offload requires EP decode or TP4 prefill-only"
578	    );
579	    start_engine(
580	        model_path,
581	        &Glm52LoadOptions {
582	            ranks,
583	            rendezvous,
584	            tp_size,
585	            dp_size,
586	            ep_size: moe_topo.expected_ep_size(),
587	        },
588	        drafter,
589	        max_model_len,
590	        prefill_only,
591	        no_prefix_cache,
592	        kv_offload,
593	        moe_topo,
594	        weight_staging,
595	        dump_graph_png,
596	    )
597	}
