894	fn start_engine(
895	    model_path: &Path,
896	    options: &Glm52LoadOptions,
897	    drafter: Glm52Drafter,
898	    requested_max_model_len: Option<usize>,
899	    prefill_only: Option<Glm52PrefillOnlyOptions>,
900	    no_prefix_cache: bool,
901	    kv_offload: Option<Glm52KvOffloadOptions>,
902	    moe_topo: Glm52MoeTopo,
903	    weight_staging: bool,
904	    dump_graph_png: Option<PathBuf>,
905	) -> Result<EngineHandle> {
906	    let startup = validate_startup(model_path, options, moe_topo, drafter.is_mtp())?;
907	    let loaded = load_rank_weights_to_gpu(model_path, &startup, moe_topo, weight_staging)?;
908	    log::info!(
909	        "GLM5.2 load-weight startup complete: hosted_ranks={:?}, rank_plan_tensors={:?}, rank_gpu_tensors={:?}, rank_gpu_bytes={:?}",
910	        startup.ranks,
911	        startup.rank_tensor_counts,
912	        loaded.report.tensor_counts,
913	        format_bytes(&loaded.report.bytes),
914	    );
915	
916	    let min_free_vram_bytes = loaded
917	        .report
918	        .free_vram_bytes
919	        .iter()
920	        .copied()
921	        .min()
922	        .expect("at least one rank loaded");
923	    // These model-build allocations land after the weight probe. Charge
924	    // exact bytes here so auto mode cannot spend them on KV and then fail the
925	    // post-build graph-capture headroom gate.
926	    let qa_kva_twin_bytes = mla_front::glm52_qa_kva_twin_bytes()?;
927	    let deepgemm_vram_charge_bytes =
928	        moe_ep::glm52_deepgemm_vram_charge_bytes(moe_topo, drafter.is_mtp())?;
929	    let post_weight_charge_bytes = qa_kva_twin_bytes
930	        .checked_add(deepgemm_vram_charge_bytes)
931	        .context("GLM5.2 post-weight VRAM charge overflow")?;
932	    let budget = derive_max_model_len(
933	        requested_max_model_len,
934	        min_free_vram_bytes.saturating_sub(post_weight_charge_bytes),
935	        &drafter,
936	        glm52_prefill_scratch_reservation(prefill_only)?,
937	        prefill_only.is_some(),
938	        moe_topo,
939	    )?;
940	    if let Some(prefill) = prefill_only {
941	        ensure!(
942	            prefill.chunk_size <= budget.max_model_len,
943	            "GLM5.2 prefill chunk size {} exceeds max_model_len {}; lower \
944	             --glm52-prefill-chunk-size or raise --max-model-len",
945	            prefill.chunk_size,
946	            budget.max_model_len,
947	        );
948	    }
949	    let max_model_len = budget.max_model_len;
950	    log::info!(
951	        "GLM5.2 max_model_len={max_model_len} ({}): min rank free VRAM {} after weights \
952	         (qa|kv_a twins {} + DeepGEMM post-weight delta {} charged), floor-pool arenas {} \
953	         across {} slots{}, reserve {}, budget {}{}",
954	        if requested_max_model_len.is_some() {
955	            "--max-model-len"
956	        } else {
957	            "VRAM-derived"
958	        },
959	        ByteSize(min_free_vram_bytes as u64),
960	        ByteSize(qa_kva_twin_bytes as u64),
961	        ByteSize(deepgemm_vram_charge_bytes as u64),
962	        ByteSize(budget.arena_bytes as u64),
963	        model::glm52_decode_slots(),
964	        if drafter.enabled() {
965	            " (draft lane included)"
966	        } else {
967	            ""
968	        },
969	        ByteSize(budget.reserve_bytes as u64),
970	        ByteSize(budget.budget_bytes as u64),
971	        prefill_only.map_or_else(String::new, |prefill| format!(
972	            ", prefill-only chunk {} (scratch reservation {})",
973	            prefill.chunk_size,
974	            ByteSize(
975	                glm52_prefill_scratch_reservation(Some(prefill))
976	                    .expect("validated prefill scratch reservation") as u64
977	            ),
978	        )),
979	    );
980	
981	    let eos_token_ids = pegainfer_core::eos::eos_token_ids(model_path, GLM52_VOCAB)?;
982	    // Exactly-known VRAM that lands AFTER the workers' free-VRAM measurement
983	    // (post-FinishKv): the DeepEP/DeepGEMM buffers created in SetupComm, and
984	    // — when DSpark is on — the draft weights reserve plus its cap-scaled
985	    // states loaded after comm setup. The measured KV fill holds these back
986	    // alongside the graph reserve.
987	    let post_finish_reserve_bytes = deepgemm_vram_charge_bytes
988	        + if drafter.is_dspark() {
989	            GLM52_DSPARK_VRAM_RESERVE_BYTES + crate::dspark::glm52_dspark_arena_bytes(max_model_len)
990	        } else {
991	            0
992	        };
993	    // build_rank_models sends SetupComm, so from inside it the DeepEP
994	    // contexts exist and their destruction is COLLECTIVE: any startup failure
995	    // from here on must broadcast Shutdown to every rank BEFORE the workers'
996	    // sequential Drop joins them one by one (the same teardown contract as
997	    // the engine exit) — otherwise the first dropped worker blocks in
998	    // the destroy barrier waiting for ranks that were never told to shut
999	    // down, and the launch error surfaces only after the ~100 s DeepEP
1000	    // device timeout. The TP LL rendezvous rejecting a topology (poison
1001	    // pill, NVLink probe) is a real failure landing exactly in this window.
1002	    let (rank_arenas, pool_blocks) = match build_rank_models(
1003	        &loaded.workers,
1004	        max_model_len,
1005	        moe_topo,
1006	        &drafter,
1007	        prefill_only.map(|options| options.chunk_size),
1008	        &startup.ranks,
1009	        startup.rendezvous.as_deref(),
1010	        budget.floor_blocks,
1011	        post_finish_reserve_bytes,
1012	    ) {
1013	        Ok(rank_arenas) => rank_arenas,
1014	        Err(err) => {
1015	            for worker in &loaded.workers {
1016	                let _ = worker.request_shutdown();
1017	            }
1018	            return Err(err);
1019	        }
1020	    };
1021	    let mirrored_early = moe_topo.uses_tensor_replicated_moe();
1022	    let local_ranks_early = if mirrored_early {
1023	        1
1024	    } else {
1025	        loaded.workers.len()
1026	    };
1027	    // The rank pools are built BEFORE the engines spawn: the store's rank
1028	    // table freezes at build, and BlockPool is a pure CPU object with no
1029	    // thread affinity. Each engine and the store share the same Arc.
1030	    let pools: Vec<Arc<BlockPool>> = (0..local_ranks_early)
1031	        .map(|_| Arc::new(BlockPool::new(GLM52_MODEL_LEN_ALIGN, pool_blocks)))
1032	        .collect();
1033	    let store_runtime = store_runtime_handle();
1034	    let post_comm_startup = || -> Result<Arc<KvStore>> {
1035	        if prefill_only.is_some() {
1036	            preflight_prefill_kernels(&loaded.workers)?;
1037	        }
1038	        if let Some(dspark_path) = drafter.dspark_path() {
1039	            load_dspark_drafters(&loaded.workers, dspark_path)?;
1040	        }
1041	        ensure_post_build_headroom(&loaded.workers)?;
1042	        let device_ordinals: Vec<usize> = (0..startup.ranks.len()).collect();
1043	        // A mirrored (TP) topology is one logical rank: worker 0's arena is
1044	        // the primary (the save side) and every other worker's is a mirror —
1045	        // MLA KV is tensor-replicated, so a tier load must land on ALL of
1046	        // them or ranks 1.. attend over never-written pages and the o_proj
1047	        // all-reduce merges the garbage identically on every rank (#847).
1048	        let (store_arenas, store_mirrors) = if mirrored_early {
1049	            let mut workers = rank_arenas.into_iter();
1050	            let primary = workers.next().context("TP arenas")?;
1051	            let mirrors = workers
1052	                .enumerate()
1053	                .map(|(index, arenas)| OffloadMirror {
1054	                    device_id: device_ordinals[1 + index] as i32,
1055	                    arenas,
1056	                })
1057	                .collect();
1058	            (vec![primary], vec![mirrors])
1059	        } else {
1060	            let ranks = rank_arenas.len();
1061	            (rank_arenas, (0..ranks).map(|_| Vec::new()).collect())
1062	        };
1063	        build_kv_store(
1064	            kv_offload.as_ref(),
1065	            store_arenas,
1066	            store_mirrors,
1067	            drafter.is_mtp(),
1068	            &device_ordinals[..local_ranks_early],
1069	            &pools,
1070	            if mirrored_early {
1071	                0
1072	            } else {
1073	                startup.ranks.start
1074	            },
1075	            &store_runtime,
1076	        )
1077	    };
1078	    let store = match post_comm_startup() {
1079	        Ok(store) => store,
1080	        Err(err) => {
1081	            for worker in &loaded.workers {
1082	                let _ = worker.request_shutdown();
1083	            }
1084	            return Err(err);
1085	        }
1086	    };
1087	    let kv_total_blocks = pool_blocks - 1;
1088	    // One autonomous engine per LOCAL logical rank (a mirrored topology
1089	    // collapses to a single engine driving every worker). Each engine owns
1090	    // its submit queue and load feed, so the frontend sees one scheduler
1091	    // partition per hosted rank.
1092	    let mirrored = moe_topo.uses_tensor_replicated_moe();
1093	    let local_ranks = if mirrored { 1 } else { loaded.workers.len() };
1094	    let (load_txs, load_rxs): (Vec<_>, Vec<_>) = (0..local_ranks)
1095	        .map(|_| {
1096	            watch::channel(SchedulerMetrics {
1097	                kv_total_blocks: kv_total_blocks as u64,
1098	                ..SchedulerMetrics::default()
1099	            })
1100	        })
1101	        .unzip();
1102	    let (mut graph_dump_request, graph_dump_response) =
1103	        match (&dump_graph_png, startup.ranks.start == 0) {
1104	            (Some(path), true) => {
1105	                let (response_tx, response_rx) = crossbeam_channel::bounded(1);
1106	                (Some((path.clone(), response_tx)), Some(response_rx))
1107	            }
1108	            _ => (None, None),
1109	        };
1110	    let worker_groups: Vec<Vec<Glm52Worker>> = if mirrored {
1111	        vec![loaded.workers]
1112	    } else {
1113	        loaded
1114	            .workers
1115	            .into_iter()
1116	            .map(|worker| vec![worker])
1117	            .collect()
1118	    };
1119	    let mut submit_txs = Vec::with_capacity(local_ranks);
1120	    let mut startup_rxs = Vec::with_capacity(local_ranks);
1121	    let mut join_handles = Vec::with_capacity(local_ranks);
1122	    for (engine_index, engine_workers) in worker_groups.into_iter().enumerate() {
1123	        let rank = if mirrored {
1124	            0
1125	        } else {
1126	            startup.ranks.start + engine_index
1127	        };
1128	        let (submit_tx, submit_rx) = mpsc::unbounded_channel();
1129	        let (startup_tx, startup_rx) = crossbeam_channel::bounded(1);
1130	        let spec = Glm52EngineSpec {
1131	            rank,
1132	            submit_rx,
1133	            workers: engine_workers,
1134	            eos_token_ids: eos_token_ids.clone(),
1135	            drafter: drafter.clone(),
1136	            prefill_chunk_size: prefill_only.map(|prefill| prefill.chunk_size),
1137	            pool: Arc::clone(&pools[engine_index]),
1138	            kv_offload: kv_offload.is_some(),
1139	            store: Arc::clone(&store),
1140	            runtime: store_runtime.clone(),
1141	            max_model_len,
1142	            no_prefix_cache,
1143	            moe_topo,
1144	            load_tx: load_txs[engine_index].clone(),
1145	            graph_dump_request: if engine_index == 0 {
1146	                graph_dump_request.take()
1147	            } else {
1148	                None
1149	            },
1150	            startup_tx,
1151	        };
1152	        match scheduler::Glm52Engine::spawn(spec) {
1153	            Ok(handle) => {
1154	                submit_txs.push(submit_tx);
1155	                startup_rxs.push(startup_rx);
1156	                join_handles.push(handle);
1157	            }
1158	            Err(err) => {
1159	                drop(submit_txs);
1160	                for handle in join_handles {
1161	                    let _ = handle.join();
1162	                }
1163	                return Err(anyhow::anyhow!(
1164	                    "failed to spawn GLM5.2 engine for rank {rank}: {err}"
1165	                ));
1166	            }
1167	        }
1168	    }
1169	    // Bootstrap barrier: every engine pre-captures its bucket graphs (the
1170	    // fixed capture sequence pairs the collectives fleet-wide — that IS the
1171	    // rendezvous) and reports once. On any failure close every queue so the
1172	    // healthy engines exit their loops and shut their workers down
1173	    // concurrently, then join them.
1174	    let abort_engines =
1175	        |submit_txs: Vec<mpsc::UnboundedSender<pegainfer_frontend::engine::SubmittedRequest>>,
1176	         join_handles: Vec<std::thread::JoinHandle<()>>| {
1177	            drop(submit_txs);
1178	            for handle in join_handles {
1179	                let _ = handle.join();
1180	            }
1181	        };
1182	    for (engine_index, startup_rx) in startup_rxs.iter().enumerate() {
1183	        let report = startup_rx.recv();
1184	        let failed = match report {
1185	            Ok(Ok(())) => None,
1186	            Ok(Err(err)) => Some(err),
1187	            Err(_) => Some(anyhow::anyhow!(
1188	                "GLM5.2 engine {engine_index} exited before reporting bootstrap"
1189	            )),
1190	        };
1191	        if let Some(err) = failed {
1192	            abort_engines(submit_txs, join_handles);
1193	            return Err(err.context("GLM5.2 engine bootstrap failed"));
1194	        }
1195	    }
1196	    if let Some(response) = graph_dump_response {
1197	        let summary = response
1198	            .recv()
1199	            .map_err(|_| anyhow::anyhow!("GLM5.2 rank 0 exited before reporting graph export"))
1200	            .and_then(|result| result);
1201	        let summary = match summary {
1202	            Ok(summary) => summary,
1203	            Err(err) => {
1204	                abort_engines(submit_txs, join_handles);
1205	                return Err(err.context("GLM5.2 CUDA Graph export failed"));
1206	            }
1207	        };
1208	        log::info!(
1209	            "GLM5.2 decode CUDA Graph exported: nodes={}, kernels={}, edges={}, dot={}, png={}",
1210	            summary.nodes,
1211	            summary.kernels,
1212	            summary.edges,
1213	            summary.dot_path.display(),
1214	            summary.png_path.display()
1215	        );
1216	    }
1217	    // Publish the launch-time cap so the frontend clamps its config.json
1218	    // max_position_embeddings (1M) at the API boundary instead of admitting
1219	    // requests the scheduler would reject (same contract as qwen3/dsv2-lite).
1220	    let servable_len = u32::try_from(max_model_len)
1221	        .expect("max_model_len is bounded by GLM52_MAX_CONTEXT and fits u32");
1222	    Ok(
1223	        EngineHandle::new_with_join_handles(submit_txs, join_handles)
1224	            .with_servable_len(servable_len)
1225	            .with_kv_capacity(KvCapacity {
1226	                total_blocks: kv_total_blocks,
1227	                block_size: GLM52_MODEL_LEN_ALIGN,
1228	            })
1229	            .with_metrics_watches(load_rxs),
1230	    )
1231	}
