1233	fn preflight_prefill_kernels(workers: &[Glm52Worker]) -> Result<()> {
1234	    let started = Instant::now();
1235	    let responses = workers
1236	        .iter()
1237	        .map(|worker| {
1238	            worker.prefill_chunk_async(Glm52PrefillBatch {
1239	                token_ids: vec![0],
1240	                positions: vec![0],
1241	                request_indptr: vec![0, 1],
1242	                block_indptr: vec![0, 1],
1243	                block_ids: vec![0],
1244	                request_slots: vec![0],
1245	                padding_block: 1,
1246	                slot_mapping: vec![0],
1247	                mtp_next_tokens: vec![Some(0)],
1248	                output_rows: Vec::new(),
1249	                sampling: Vec::new(),
1250	                seed: 0,
1251	            })
1252	        })
1253	        .collect::<Result<Vec<_>>>()?;
1254	    for (rank, response) in responses.into_iter().enumerate() {
1255	        response.recv().map_err(|_| {
1256	            anyhow::anyhow!("GLM5.2 rank {rank} dropped its prefill preflight response")
1257	        })??;
1258	    }
1259	    log::info!(
1260	        "GLM5.2 TP4 prefill kernel preflight completed on all ranks in {:.3}s",
1261	        started.elapsed().as_secs_f64()
1262	    );
1263	    Ok(())
1264	}
