1287	/// Re-probe every rank once everything the reserve constants stand in for is
1288	/// resident (model arenas, dequanted MLA weights, DeepEP contexts, optional
1289	/// drafter): if any rank is left with less headroom than the whole-step
1290	/// graph instantiations and allocator slack need, fail the launch with the
1291	/// numbers — a reserve/ledger drift must crash here, not as a mid-serving
1292	/// OOM that tears the collective group down.
1293	fn ensure_post_build_headroom(workers: &[Glm52Worker]) -> Result<()> {
1294	    let responses = workers
1295	        .iter()
1296	        .map(Glm52Worker::free_vram_async)
1297	        .collect::<Result<Vec<_>>>()?;
1298	    let mut per_rank = Vec::with_capacity(responses.len());
1299	    for (rank, response) in responses.into_iter().enumerate() {
1300	        let free = response
1301	            .recv()
1302	            .map_err(|_| anyhow::anyhow!("GLM5.2 rank {rank} dropped its VRAM-probe response"))??;
1303	        ensure!(
1304	            free >= GLM52_POST_BUILD_MIN_FREE_BYTES,
1305	            "GLM5.2 rank {rank} has only {} free VRAM after build (< {} headroom for graph \
1306	             capture); lower --max-model-len or free device memory",
1307	            ByteSize(free as u64),
1308	            ByteSize(GLM52_POST_BUILD_MIN_FREE_BYTES as u64),
1309	        );
1310	        per_rank.push(free);
1311	    }
1312	    log::info!(
1313	        "GLM5.2 post-build free VRAM per rank: {:?}",
1314	        format_bytes(&per_rank)
1315	    );
1316	    Ok(())
1317	}
1318	
1319	/// Build every rank's resident model in the measured two phases, then create
1320	/// the collective contexts. Phases on purpose: the build is per-rank and can
1321	/// fail (OOM, packaging drift) — every rank must report success BEFORE
1322	/// anyone enters context creation, or a single failure strands peer ranks in
1323	/// a collective init with no useful error. Between the phases the fleet's
1324	/// measured free-VRAM minimum decides the KV pool block count, published
1325	/// process-wide (the schedulers' `BlockPool` reads it) before any FinishKv
1326	/// dispatch. TP4 currently stops after the per-rank build, before entering
1327	/// any EP/TP collective setup.
1328	#[allow(clippy::too_many_arguments)]
1329	fn build_rank_models(
1330	    workers: &[Glm52Worker],
1331	    max_model_len: usize,
1332	    moe_topo: Glm52MoeTopo,
1333	    drafter: &Glm52Drafter,
1334	    prefill_chunk_size: Option<usize>,
1335	    ranks: &Range<usize>,
1336	    rendezvous: Option<&str>,
1337	    floor_blocks: usize,
1338	    post_finish_reserve_bytes: usize,
1339	) -> Result<(Vec<Vec<ArenaSpec>>, usize)> {
1340	    let build_started = Instant::now();
1341	    let prefill_only = prefill_chunk_size.is_some();
1342	    let responses = workers
1343	        .iter()
1344	        .map(|worker| {
1345	            worker.build_fixed_async(max_model_len, moe_topo, drafter.clone(), prefill_chunk_size)
1346	        })
1347	        .collect::<Result<Vec<_>>>()?;
1348	    let mut rank_free_bytes = Vec::with_capacity(responses.len());
1349	    for (local_index, response) in responses.into_iter().enumerate() {
1350	        // Label with the global rank, not the local worker slot — on a
1351	        // multi-process fleet every process would otherwise call its first
1352	        // worker "rank 0".
1353	        let rank = ranks.start + local_index;
1354	        rank_free_bytes.push(
1355	            response.recv().map_err(|_| {
1356	                anyhow::anyhow!("GLM5.2 rank {rank} dropped its fixed-build response")
1357	            })?? as usize,
1358	        );
1359	    }
1360	    let min_free_bytes = rank_free_bytes
1361	        .iter()
1362	        .copied()
1363	        .min()
1364	        .expect("at least one rank built");
1365	    // The exact per-block slab cost, taken from the SAME ledger the
1366	    // allocations use (linear in blocks, so one difference is the marginal):
1367	    // 78 MLA pages + the full-indexer index-K blocks + the MTP mirror and
1368	    // the prefill unpacked page, whichever of those this launch carries.
1369	    let slab_bytes_per_block = glm52_cap_bytes(
1370	        max_model_len,
1371	        floor_blocks + 1,
1372	        drafter,
1373	        prefill_only,
1374	        moe_topo,
1375	    )?
1376	    .saturating_sub(glm52_cap_bytes(
1377	        max_model_len,
1378	        floor_blocks,
1379	        drafter,
1380	        prefill_only,
1381	        moe_topo,
1382	    )?);
1383	    let pool_blocks = match std::env::var("GLM52_KV_POOL_BLOCKS")
1384	        .ok()
1385	        .and_then(|v| v.parse::<usize>().ok())
1386	    {
1387	        Some(pinned) => {
1388	            // A pin below the one-request floor would advertise a cap no
1389	            // request can ever fit — admission then parks the impossible
1390	            // request at the FIFO head forever. And a pin above the measured
1391	            // affordable count would either fail slab allocation outright or
1392	            // eat into the graph reserve and die at pre-capture — the A/B
1393	            // knob must stay inside both fences. Refuse loudly either way.
1394	            let one_request = glm52_one_request_pool_blocks(max_model_len);
1395	            ensure!(
1396	                pinned >= one_request,
1397	                "GLM52_KV_POOL_BLOCKS={pinned} is below the {one_request}-block one-request \
1398	                 floor for max_model_len {max_model_len}"
1399	            );
1400	            let affordable = glm52_measured_pool_blocks(
1401	                min_free_bytes,
1402	                post_finish_reserve_bytes,
1403	                slab_bytes_per_block,
1404	                one_request,
1405	            );
1406	            ensure!(
1407	                pinned <= affordable,
1408	                "GLM52_KV_POOL_BLOCKS={pinned} exceeds the {affordable}-block measured \
1409	                 affordable count (min rank free {} - reserves at {} per block)",
1410	                ByteSize(min_free_bytes as u64),
1411	                ByteSize(slab_bytes_per_block as u64),
1412	            );
1413	            pinned
1414	        }
1415	        None => glm52_measured_pool_blocks(
1416	            min_free_bytes,
1417	            post_finish_reserve_bytes,
1418	            slab_bytes_per_block,
1419	            floor_blocks,
1420	        ),
1421	    };
1422	    log::info!(
1423	        "GLM5.2 KV pool: {} blocks ({} tokens, {} past the {}-slot nominal) — the measured \
1424	         free-VRAM fill (min rank free {} after the fixed build, graph reserve {}, post-finish \
1425	         charges {}, {}/block) decouples pool capacity from the {max_model_len}-token cap (#818)",
1426	        pool_blocks,
1427	        pool_blocks * GLM52_MODEL_LEN_ALIGN,
1428	        pool_blocks.saturating_sub(glm52_nominal_pool_blocks(max_model_len)),
1429	        model::glm52_decode_slots(),
1430	        ByteSize(min_free_bytes as u64),
1431	        ByteSize(glm52_graph_reserve_bytes() as u64),
1432	        ByteSize(post_finish_reserve_bytes as u64),
1433	        ByteSize(slab_bytes_per_block as u64),
1434	    );
1435	    let responses = workers
1436	        .iter()
1437	        .map(|worker| worker.finish_kv_async(pool_blocks))
1438	        .collect::<Result<Vec<_>>>()?;
1439	    let mut rank_arenas = Vec::with_capacity(responses.len());
1440	    for (local_index, response) in responses.into_iter().enumerate() {
1441	        let rank = ranks.start + local_index;
1442	        rank_arenas.push(
1443	            response
1444	                .recv()
1445	                .map_err(|_| anyhow::anyhow!("GLM5.2 rank {rank} dropped its build response"))??,
1446	        );
1447	    }
1448	    let unique_id = if moe_topo.uses_ep_expert_bundles() {
1449	        // One-time bootstrap rendezvous: the rank-0-hosting process generates
1450	        // and serves the id, every other process fetches it (single-process
1451	        // fleets generate in-process and never touch the network).
1452	        rendezvous::unique_id(moe_topo.expected_ep_size(), ranks, rendezvous)?
1453	    } else {
1454	        // TP allreduce bootstrap just needs one NCCL unique id; ride the EP8
1455	        // shim's generator.
1456	        pegainfer_kernels::ops::glm52_ep_deepep_unique_id(8)?
1457	    };
1458	    let tp_exchange = moe_topo
1459	        .uses_tensor_replicated_moe()
1460	        .then(|| std::sync::Arc::new(crate::moe_tp::Glm52TpExchange::new(moe_topo.device_count())));
1461	    if tp_exchange.is_some() {
1462	        // The prefill-only NCCL all-reduce moves ~200 MB per layer; NCCL's
1463	        // default channel count on this single-host NVLink topology comes up
1464	        // as 2 and caps the ring at ~46 GB/s (measured 8.7 ms per 16K-row
1465	        // all-reduce). 16..32 channels restores ~5x (measured 1.6 ms).
1466	        // Set BEFORE any worker thread initializes its communicator; user
1467	        // overrides win. Single-threaded here, so set_var is race-free.
1468	        for (key, value) in [("NCCL_MIN_NCHANNELS", "16"), ("NCCL_MAX_NCHANNELS", "32")] {
1469	            if std::env::var_os(key).is_none() {
1470	                unsafe { std::env::set_var(key, value) };
1471	            }
1472	        }
1473	    }
1474	    let responses = workers
1475	        .iter()
1476	        .map(|worker| worker.setup_comm_async(unique_id, moe_topo, tp_exchange.clone()))
1477	        .collect::<Result<Vec<_>>>()?;
1478	    for (local_index, response) in responses.into_iter().enumerate() {
1479	        let rank = ranks.start + local_index;
1480	        response
1481	            .recv()
1482	            .map_err(|_| anyhow::anyhow!("GLM5.2 rank {rank} dropped its comm-setup response"))??;
1483	    }
1484	    log::info!(
1485	        "GLM5.2 rank models built in {:.2}s (weights adopted in place + {:?} contexts up)",
1486	        build_started.elapsed().as_secs_f64(),
1487	        moe_topo
1488	    );
1489	    Ok((rank_arenas, pool_blocks))
