165	/// The page-first slice map of one slab page: per-layer offsets in layer
166	/// order, then the layer-78 MTP committed-mirror slices. A pure function of
167	/// the architecture — the ONE construction shared by `finish_kv`, the MTP
168	/// attach, and the layout unit test, so the offset table cannot drift from
169	/// the wire constants.
170	struct Glm52PageLayout {
171	    layers: Vec<Glm52LayerCaches>,
172	    /// Layer-78 committed mirrors (native MTP): radix hits reuse L78 KV by
173	    /// pool page id, so the mirrors ride the same page as the target layers.
174	    mtp: Glm52LayerCaches,
175	}
176	
177	fn glm52_page_layout() -> Glm52PageLayout {
178	    let mut offset = 0usize;
179	    let mut layers = Vec::with_capacity(GLM52_LAYERS);
180	    for layer in 0..GLM52_LAYERS {
181	        let mla_offset = offset;
182	        offset += GLM52_KV_PAGE_MLA_BYTES;
183	        let index_k_offset = glm52_layer_has_full_indexer(layer).then(|| {
184	            let at = offset;
185	            offset += GLM52_KV_PAGE_IDXK_BYTES;
186	            at
187	        });
188	        layers.push(Glm52LayerCaches {
189	            mla_offset,
190	            index_k_offset,
191	        });
192	    }
193	    let mtp = Glm52LayerCaches {
194	        mla_offset: offset,
195	        index_k_offset: Some(offset + GLM52_KV_PAGE_MLA_BYTES),
196	    };
197	    offset += GLM52_KV_PAGE_MLA_BYTES + GLM52_KV_PAGE_IDXK_BYTES;
198	    assert_eq!(
199	        offset, GLM52_KV_PAGE_CONTENT_BYTES,
200	        "GLM5.2 page layout drifted from its wire constant"
201	    );
202	    Glm52PageLayout { layers, mtp }
203	}
